import{_ as a,o as s,c as e,ag as n}from"./chunks/framework.i8sMDeRW.js";const g=JSON.parse('{"title":"AI 产品定价策略","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-monetization/pricing-strategies.md","filePath":"guide/09-monetization/pricing-strategies.md","lastUpdated":1782288443000}'),d={name:"guide/09-monetization/pricing-strategies.md"};function r(i,t,l,o,p,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-产品定价策略" tabindex="-1">AI 产品定价策略 <a class="header-anchor" href="#ai-产品定价策略" aria-label="Permalink to &quot;AI 产品定价策略&quot;">​</a></h1><blockquote><p>面向专业产品经理的完整定价框架，覆盖从成本结构、计费模型、免费层设计到企业化商业策略的关键决策点。</p><p><strong>更新说明</strong>：本文按 <strong>2026-05-15</strong> 的公开价格与行业实践重写了行业案例。AI 产品价格、模型名、使用额度变化很快，涉及具体美元价格的内容只应作为当期参考，落地前必须以各产品官网为准。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-ai-产品定价的独特性">AI 产品定价的独特性</a></li><li><a href="#2-主要定价模式详解">主要定价模式详解</a></li><li><a href="#3-定价决策框架四维分析表">定价决策框架：四维分析表</a></li><li><a href="#4-免费层设计">免费层设计</a></li><li><a href="#5-企业定价策略">企业定价策略</a></li><li><a href="#6-真实行业参考2026-05">真实行业参考（2026-05）</a></li><li><a href="#7-附录定价工具箱">附录：定价工具箱</a></li><li><a href="#8-参考来源">参考来源</a></li></ol><hr><h2 id="_1-ai-产品定价的独特性" tabindex="-1">1. AI 产品定价的独特性 <a class="header-anchor" href="#_1-ai-产品定价的独特性" aria-label="Permalink to &quot;1. AI 产品定价的独特性&quot;">​</a></h2><h3 id="_1-1-可变成本主导-vs-固定成本主导" tabindex="-1">1.1 可变成本主导 vs 固定成本主导 <a class="header-anchor" href="#_1-1-可变成本主导-vs-固定成本主导" aria-label="Permalink to &quot;1.1 可变成本主导 vs 固定成本主导&quot;">​</a></h3><p>传统 SaaS 的定价逻辑建立在 <strong>“高固定成本 + 边际成本趋近于零”</strong> 之上。一旦软件开发完成，每增加一个用户的边际成本通常较低，这使得传统 SaaS 可以采用较激进的免费增值策略。</p><p>AI 产品则不完全适用这个假设。每一次模型推理、图像生成、语音转写、Agent 工具调用都可能消耗真实算力，边际成本 <strong>不为零</strong>，且会随模型能力、上下文长度、输出长度、并发需求、工具链复杂度上升。</p><table tabindex="0"><thead><tr><th>维度</th><th>传统 SaaS</th><th>AI 产品</th></tr></thead><tbody><tr><td>成本结构</td><td>高固定成本，低边际成本</td><td>高固定成本 + 高可变成本</td></tr><tr><td>边际成本趋势</td><td>随规模摊薄</td><td>随 token、任务、Agent 步骤线性或阶梯增长</td></tr><tr><td>定价弹性</td><td>免费层可较慷慨</td><td>免费层必须强控成本与滥用</td></tr><tr><td>单位经济学</td><td>用户数 / 席位数</td><td>token、图片、音视频分钟、工具调用、Agent 运行</td></tr><tr><td>利润天花板</td><td>主要取决于获客与留存</td><td>同时受推理成本、模型路由、限额设计约束</td></tr></tbody></table><blockquote><p><strong>核心洞见</strong>：AI 产品经理必须像运营一个“有制造成本的数字产品”一样思考定价。你卖的每一次回答、每张图、每段代码、每个 Agent 运行，都有真实成本。</p></blockquote><h3 id="_1-2-从-三边约束-到-四边约束" tabindex="-1">1.2 从“三边约束”到“四边约束” <a class="header-anchor" href="#_1-2-从-三边约束-到-四边约束" aria-label="Permalink to &quot;1.2 从“三边约束”到“四边约束”&quot;">​</a></h3><p>AI 产品定价不再只是“用户愿意付多少钱”的问题，而是一个多约束优化问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              ┌──────────────┐</span></span>
<span class="line"><span>              │  用户支付意愿  │</span></span>
<span class="line"><span>              └──────┬───────┘</span></span>
<span class="line"><span>                     │</span></span>
<span class="line"><span>        ┌────────────┼────────────┐</span></span>
<span class="line"><span>        │            │            │</span></span>
<span class="line"><span>        ▼            ▼            ▼</span></span>
<span class="line"><span>  ┌──────────┐ ┌──────────┐ ┌──────────┐</span></span>
<span class="line"><span>  │ 模型成本  │ │ 产品价值  │ │ 竞品锚点  │</span></span>
<span class="line"><span>  └────┬─────┘ └────┬─────┘ └────┬─────┘</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>       └────────────┼────────────┘</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>             ┌──────────────┐</span></span>
<span class="line"><span>             │  风险与合规成本 │</span></span>
<span class="line"><span>             └──────────────┘</span></span></code></pre></div><p>四个关键约束分别是：</p><ol><li><strong>用户支付意愿</strong>：目标用户愿意为 AI 能力多付多少钱？是个人订阅、团队预算，还是企业采购预算？</li><li><strong>模型与算力成本</strong>：输入、输出、缓存、图像、音频、工具调用、Agent 步数分别消耗多少？</li><li><strong>产品价值感知</strong>：用户为“省时间、提质量、降风险、增收入”付费，而不是为 token 付费。</li><li><strong>竞争与合规成本</strong>：竞品价格形成锚点，企业客户还会为安全、审计、数据隔离、SLA 支付溢价。</li></ol><h3 id="_1-3-成本透明度悖论" tabindex="-1">1.3 成本透明度悖论 <a class="header-anchor" href="#_1-3-成本透明度悖论" aria-label="Permalink to &quot;1.3 成本透明度悖论&quot;">​</a></h3><p>AI 产品有一个特殊矛盾：</p><ul><li><strong>完全隐藏成本</strong>：用户不知道每次请求的成本，容易过度使用，导致产品必须限流、降速或降低模型质量。</li><li><strong>完全暴露成本</strong>：用户看到 token、credit、GPU 分钟后，可能变得“抠门”，不敢充分使用 AI，反而降低产品价值感。</li></ul><p>因此，现代 AI 产品越来越常用 <strong>“用户看得懂的配额单位”</strong>：</p><table tabindex="0"><thead><tr><th>用户看到的单位</th><th>背后可能对应的成本</th></tr></thead><tbody><tr><td>消息 / 次数</td><td>token + 输出长度 + 工具调用</td></tr><tr><td>AI credits</td><td>token、模型等级、工具调用、Agent 步骤的抽象封装</td></tr><tr><td>Fast GPU hours</td><td>图片/视频生成的 GPU 时间</td></tr><tr><td>Premium requests</td><td>高级模型调用、长上下文、复杂任务</td></tr><tr><td>Agent runs</td><td>多步骤推理 + 检索 + 工具执行 + 写回动作</td></tr></tbody></table><h3 id="_1-4-2026-年以后更重要的新变量-agent-成本" tabindex="-1">1.4 2026 年以后更重要的新变量：Agent 成本 <a class="header-anchor" href="#_1-4-2026-年以后更重要的新变量-agent-成本" aria-label="Permalink to &quot;1.4 2026 年以后更重要的新变量：Agent 成本&quot;">​</a></h3><p>早期 AI 产品主要按“单次聊天”或“单次生成”计算成本。现在 Agent 产品会连续执行多个步骤：检索资料、读数据库、调用工具、写文档、发通知、生成代码、跑测试。</p><p>这意味着成本从：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次请求成本 = 输入 token + 输出 token</span></span></code></pre></div><p>变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次 Agent 成本 = 多轮模型调用 + 检索成本 + 工具调用成本 + 写入/执行成本 + 失败重试成本</span></span></code></pre></div><p>因此，Agent 产品定价不应简单承诺“无限使用”，而应设计为：</p><ul><li>订阅费覆盖基础使用；</li><li>included usage 覆盖正常工作量；</li><li>超额用 credit / usage-based billing；</li><li>企业客户可购买承诺用量、池化额度、私有部署或专属容量。</li></ul><hr><h2 id="_2-主要定价模式详解" tabindex="-1">2. 主要定价模式详解 <a class="header-anchor" href="#_2-主要定价模式详解" aria-label="Permalink to &quot;2. 主要定价模式详解&quot;">​</a></h2><h3 id="_2-1-按-token-用量计费-usage-based-pricing" tabindex="-1">2.1 按 Token / 用量计费 (Usage-Based Pricing) <a class="header-anchor" href="#_2-1-按-token-用量计费-usage-based-pricing" aria-label="Permalink to &quot;2.1 按 Token / 用量计费 (Usage-Based Pricing)&quot;">​</a></h3><p><strong>适用场景</strong>：API、开发者平台、模型服务、企业后台批处理、可量化消耗的 AI 基础设施。</p><p><strong>典型代表</strong>：OpenAI API、Claude API、Google Gemini API、各类模型网关。</p><p><strong>优点</strong>：</p><ul><li>收入与成本天然对齐；</li><li>对开发者透明，便于成本核算；</li><li>低门槛进入，适合按需扩展。</li></ul><p><strong>缺点</strong>：</p><ul><li>用户难以预测账单；</li><li>用户可能抑制使用；</li><li>ARR 预测不如席位订阅稳定；</li><li>对 C 端用户理解门槛高。</li></ul><p><strong>设计要点</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>策略</th><th>注意事项</th></tr></thead><tbody><tr><td>输入 / 输出分价</td><td>输出通常更贵</td><td>长回答、代码生成、报告生成成本高</td></tr><tr><td>缓存输入</td><td>对重复上下文降价</td><td>适合知识库、代码库、长上下文应用</td></tr><tr><td>批处理 / 慢速模式</td><td>低价换延迟</td><td>适合离线任务、非实时场景</td></tr><tr><td>数据驻留 / 区域处理</td><td>溢价</td><td>企业合规需求强时可单独收费</td></tr><tr><td>用量上限</td><td>硬上限 + 告警</td><td>避免账单冲击</td></tr><tr><td>预付费 / 承诺消费</td><td>换取折扣</td><td>提高收入确定性</td></tr></tbody></table><p><strong>定价公式参考</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单次请求成本 = 输入 token × 输入单价</span></span>
<span class="line"><span>             + 缓存输入 token × 缓存单价</span></span>
<span class="line"><span>             + 输出 token × 输出单价</span></span>
<span class="line"><span>             + 工具 / 图像 / 音频等额外成本</span></span>
<span class="line"><span></span></span>
<span class="line"><span>月账单 = Σ(所有请求成本) + 固定订阅费（如有）</span></span></code></pre></div><p><strong>实战案例：OpenAI API 成本估算（2026-05）</strong></p><p>以一次典型对话为例：10 轮来回，每轮约 500 输入 token + 200 输出 token。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总输入 = 10 × 500 = 5,000 token</span></span>
<span class="line"><span>总输出 = 10 × 200 = 2,000 token</span></span></code></pre></div><p>按 OpenAI 公布的标准处理价，GPT-5.4 为 $2.50 / 1M 输入 token、$15 / 1M 输出 token；GPT-5.4 mini 为 $0.75 / 1M 输入 token、$4.50 / 1M 输出 token；GPT-5.5 为 $5 / 1M 输入 token、$30 / 1M 输出 token。</p><table tabindex="0"><thead><tr><th>模型</th><th>输入成本</th><th>输出成本</th><th>单会话估算</th></tr></thead><tbody><tr><td>GPT-5.4 mini</td><td>5,000 × $0.75 / 1M = $0.00375</td><td>2,000 × $4.50 / 1M = $0.009</td><td><strong>$0.01275</strong></td></tr><tr><td>GPT-5.4</td><td>5,000 × $2.50 / 1M = $0.0125</td><td>2,000 × $15 / 1M = $0.03</td><td><strong>$0.0425</strong></td></tr><tr><td>GPT-5.5</td><td>5,000 × $5 / 1M = $0.025</td><td>2,000 × $30 / 1M = $0.06</td><td><strong>$0.085</strong></td></tr></tbody></table><p>如果每月 100 万活跃用户，每人每月 100 次这样的会话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GPT-5.4 mini: 100M 会话 × $0.01275 ≈ $1.275M / 月</span></span>
<span class="line"><span>GPT-5.4:      100M 会话 × $0.0425  ≈ $4.25M / 月</span></span>
<span class="line"><span>GPT-5.5:      100M 会话 × $0.085   ≈ $8.5M / 月</span></span></code></pre></div><p>这解释了为什么 C 端免费层必须依赖小模型、缓存、限额、降速与模型路由，而不能让所有用户无限使用最贵模型。</p><h3 id="_2-2-按席位订阅-per-seat-subscription" tabindex="-1">2.2 按席位订阅 (Per-Seat Subscription) <a class="header-anchor" href="#_2-2-按席位订阅-per-seat-subscription" aria-label="Permalink to &quot;2.2 按席位订阅 (Per-Seat Subscription)&quot;">​</a></h3><p><strong>适用场景</strong>：AI 是工作流增强能力，用户按人购买，尤其适合企业协作工具、办公套件、知识库、代码 IDE。</p><p><strong>典型代表</strong>：ChatGPT Business、Claude Team、Microsoft 365 Copilot Business、GitHub Copilot Business、Cursor Teams。</p><p><strong>优点</strong>：</p><ul><li>收入稳定，方便企业采购；</li><li>用户不需要理解 token；</li><li>便于和权限、审计、团队管理、安全功能打包。</li></ul><p><strong>缺点</strong>：</p><ul><li>重度用户可能让成本失控；</li><li>轻度用户会觉得不值；</li><li>席位价必须和 included usage、超额计费配合。</li></ul><p><strong>定价计算公式</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标席位价 = 预期月均推理成本 / (1 - 目标毛利率)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：</span></span>
<span class="line"><span>如果一个席位月均推理成本为 $5，目标毛利率 70%，</span></span>
<span class="line"><span>目标席位价 = $5 / (1 - 70%) = $16.67</span></span></code></pre></div><p>现实中，越来越多 AI SaaS 不是纯席位订阅，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>席位订阅费 + 包含用量 + 超额按量 / credits + 企业治理能力</span></span></code></pre></div><h3 id="_2-3-按任务-输出计费-output-based-pricing" tabindex="-1">2.3 按任务 / 输出计费 (Output-Based Pricing) <a class="header-anchor" href="#_2-3-按任务-输出计费-output-based-pricing" aria-label="Permalink to &quot;2.3 按任务 / 输出计费 (Output-Based Pricing)&quot;">​</a></h3><p><strong>适用场景</strong>：输出物边界清晰，用户能直观看到结果价值。</p><p><strong>典型代表</strong>：图片生成、视频生成、语音转写、自动报告、代码审查、数据分析任务、后台 Agent 运行。</p><p><strong>优点</strong>：</p><ul><li>用户为“结果”付费，而不是为 token 付费；</li><li>定价更容易理解；</li><li>适合包装成 credit、任务包、GPU 时间包。</li></ul><p><strong>缺点</strong>：</p><ul><li>“一次任务”的边界难定义；</li><li>失败重试、反复修改会放大成本；</li><li>需要防止自动化滥用和并发刷量。</li></ul><p><strong>设计要点</strong>：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>常见定价单位</th><th>成本控制</th></tr></thead><tbody><tr><td>文生图</td><td>张数、GPU 分钟、Fast hours</td><td>并发限制、队列优先级、Relax 模式</td></tr><tr><td>视频生成</td><td>秒 / 分钟、分辨率、队列等级</td><td>分辨率限制、生成时长限制</td></tr><tr><td>代码生成</td><td>premium requests、agent runs、AI credits</td><td>高级模型限额、项目级用量池</td></tr><tr><td>自动报告</td><td>报告份数、数据量、刷新频率</td><td>数据行数、上下文长度、缓存</td></tr><tr><td>Agent 自动化</td><td>run、step、credit</td><td>步骤上限、工具白名单、失败重试上限</td></tr><tr><td>语音 / 转写</td><td>分钟数、字符数</td><td>批处理、低优先级队列</td></tr></tbody></table><h3 id="_2-4-混合模式-订阅-用量-免费层" tabindex="-1">2.4 混合模式：订阅 + 用量 + 免费层 <a class="header-anchor" href="#_2-4-混合模式-订阅-用量-免费层" aria-label="Permalink to &quot;2.4 混合模式：订阅 + 用量 + 免费层&quot;">​</a></h3><p>这是 2026 年最常见的 AI 产品定价结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>免费层：基础模型 + 限额 + 慢速 / 低优先级</span></span>
<span class="line"><span>入门层：固定月费 + 更多消息 / 更多上传 / 更多模型</span></span>
<span class="line"><span>专业层：更强模型 + 更长上下文 + 更多 Agent / Codex / Deep Research 用量</span></span>
<span class="line"><span>团队层：席位 + 管理后台 + SSO + 数据保护 + 团队上下文</span></span>
<span class="line"><span>企业层：自定义报价 + 用量承诺 + 审计 + 合规 + 私有化 / 专属容量</span></span></code></pre></div><p><strong>混合模式的关键思想</strong>：</p><ul><li>对轻度用户：固定订阅让用户买“安心”；</li><li>对重度用户：用量或 credit 防止成本失控；</li><li>对企业用户：治理、安全、合规、数据连接能力本身就是价值；</li><li>对平台方：通过模型路由、缓存、批处理、队列优先级来管理毛利率。</li></ul><hr><h2 id="_3-定价决策框架-四维分析表" tabindex="-1">3. 定价决策框架：四维分析表 <a class="header-anchor" href="#_3-定价决策框架-四维分析表" aria-label="Permalink to &quot;3. 定价决策框架：四维分析表&quot;">​</a></h2><h3 id="_3-1-四维矩阵" tabindex="-1">3.1 四维矩阵 <a class="header-anchor" href="#_3-1-四维矩阵" aria-label="Permalink to &quot;3.1 四维矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>子问题</th><th>对定价的影响</th></tr></thead><tbody><tr><td><strong>1. 产品类型</strong></td><td>核心 AI 产品还是 AI 辅助功能？</td><td>核心 → 用量 / 任务 / 订阅混合；辅助 → 捆绑 / 席位</td></tr><tr><td><strong>2. 用户群体</strong></td><td>开发者、知识工作者、创作者、大众消费者、企业？</td><td>开发者 → API 用量；知识工作者 → 席位；创作者 → 任务包；企业 → 合约</td></tr><tr><td><strong>3. 使用频率</strong></td><td>高频低价值还是低频高价值？</td><td>高频 → 订阅 + 限额；低频 → 按次 / credit</td></tr><tr><td><strong>4. 成本结构</strong></td><td>推理成本、工具调用、数据连接、合规成本占比如何？</td><td>成本高 → 严控免费层；成本低 → 可扩大免费体验</td></tr></tbody></table><h3 id="_3-2-决策树" tabindex="-1">3.2 决策树 <a class="header-anchor" href="#_3-2-决策树" aria-label="Permalink to &quot;3.2 决策树&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[产品类型]</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── AI 原生产品</span></span>
<span class="line"><span>    │    ├── C 端助手 → Freemium + Plus/Pro + usage caps</span></span>
<span class="line"><span>    │    ├── 开发者 API → Token / 用量计费 + 承诺消费</span></span>
<span class="line"><span>    │    ├── 创作工具 → 任务 / GPU 时间 / credits</span></span>
<span class="line"><span>    │    └── Agent 平台 → 席位 + Agent runs / credits</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── AI 辅助功能</span></span>
<span class="line"><span>         ├── 企业工具 → 席位订阅 + 管理 / 安全 / 合规</span></span>
<span class="line"><span>         ├── 办公套件 → 原有订阅加购 / 高级层打包</span></span>
<span class="line"><span>         └── 垂直 SaaS → 按业务价值打包进套餐</span></span></code></pre></div><h3 id="_3-3-定价策略速查表" tabindex="-1">3.3 定价策略速查表 <a class="header-anchor" href="#_3-3-定价策略速查表" aria-label="Permalink to &quot;3.3 定价策略速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景画像</th><th>定价建议</th><th>参考月费 / 计费方式</th><th>毛利率关注点</th></tr></thead><tbody><tr><td>大众聊天助手</td><td>Freemium + Plus/Pro</td><td>$20 / $100 / $200 常见锚点</td><td>重度用户成本与限额</td></tr><tr><td>编程助手</td><td>免费层 + 个人订阅 + 团队席位 + 高级模型限额</td><td>$10-40/人/月 + 超额</td><td>Agent 与高级模型成本</td></tr><tr><td>企业知识库 AI</td><td>席位 + 数据连接 + 企业安全</td><td>$20-100+/席位/月</td><td>检索、上下文、合规成本</td></tr><tr><td>图像生成</td><td>GPU 时间 / credits + 订阅</td><td>$10-120/月</td><td>并发、队列、失败重试</td></tr><tr><td>API 服务</td><td>纯用量 + 承诺消费</td><td>按 1M token / 分钟 / 图片</td><td>模型成本、缓存命中率</td></tr><tr><td>垂直 AI Agent</td><td>订阅 + 每任务 / 每结果</td><td>$5-200/任务或按月打包</td><td>工具调用与人工替代价值</td></tr></tbody></table><hr><h2 id="_4-免费层设计" tabindex="-1">4. 免费层设计 <a class="header-anchor" href="#_4-免费层设计" aria-label="Permalink to &quot;4. 免费层设计&quot;">​</a></h2><h3 id="_4-1-免费额度给多少" tabindex="-1">4.1 免费额度给多少？ <a class="header-anchor" href="#_4-1-免费额度给多少" aria-label="Permalink to &quot;4.1 免费额度给多少？&quot;">​</a></h3><p>免费层的目标不是“越慷慨越好”，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>让用户完成 1-3 个完整工作流，并体验到核心价值，同时把单位经济学控制在可承受范围内。</span></span></code></pre></div><p>不要在文档里写死“每天 X 条 GPT-4o / Claude 多少条”这样的额度，因为模型和限额变化极快。更稳妥的写法是：</p><table tabindex="0"><thead><tr><th>产品类型</th><th>免费层目标</th><th>推荐限制方式</th></tr></thead><tbody><tr><td>聊天助手</td><td>让用户完成若干次真实问题求解</td><td>低成本模型 + 动态消息上限 + 高峰限流</td></tr><tr><td>编程助手</td><td>体验补全、问答、一次简单 agent 任务</td><td>补全限额 + 高级模型请求限额</td></tr><tr><td>图像生成</td><td>生成 1-3 张满意作品</td><td>低速队列 + 水印 / 分辨率限制</td></tr><tr><td>企业知识库</td><td>让团队完成一个小型知识库问答试点</td><td>限文档数、成员数、检索次数</td></tr><tr><td>Agent 自动化</td><td>体验一次自动化闭环</td><td>限 run 数、step 数、触发频率</td></tr></tbody></table><p><strong>免费层成本估算公式</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>免费用户月成本 = 日均请求数 × 30 × 单次平均成本</span></span>
<span class="line"><span>              + 文件 / 图像 / 工具调用成本</span></span>
<span class="line"><span>              + 滥用与失败重试成本</span></span></code></pre></div><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果免费用户每天 10 次低成本模型请求，单次成本 $0.001：</span></span>
<span class="line"><span>月成本 = 10 × 30 × $0.001 = $0.30 / 用户 / 月</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果有 100 万免费活跃用户：</span></span>
<span class="line"><span>月成本 = $300,000</span></span></code></pre></div><p>如果单次成本从 $0.001 上升到 $0.01，月成本会直接变成 $3,000,000。因此，免费层必须优先做模型路由与成本保护。</p><h3 id="_4-2-免费层的成本控制策略" tabindex="-1">4.2 免费层的成本控制策略 <a class="header-anchor" href="#_4-2-免费层的成本控制策略" aria-label="Permalink to &quot;4.2 免费层的成本控制策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>描述</th><th>效果</th></tr></thead><tbody><tr><td><strong>模型路由</strong></td><td>简单任务走小模型，复杂任务走强模型</td><td>降低整体平均成本</td></tr><tr><td><strong>动态限额</strong></td><td>根据负载、账号信誉、历史行为调整额度</td><td>平衡体验与成本</td></tr><tr><td><strong>高峰降级</strong></td><td>高峰时免费用户排队或慢速响应</td><td>平滑 GPU 负载</td></tr><tr><td><strong>输出长度限制</strong></td><td>限制免费层输出 token</td><td>控制最贵的输出成本</td></tr><tr><td><strong>上下文窗口限制</strong></td><td>免费层减少历史上下文和文件大小</td><td>降低输入与检索成本</td></tr><tr><td><strong>缓存优先</strong></td><td>高频问题、模板回答、公开知识优先缓存</td><td>降低重复请求成本</td></tr><tr><td><strong>滥用检测</strong></td><td>限制批量注册、脚本刷量、自动化调用</td><td>防止成本被攻击</td></tr><tr><td><strong>Agent step 上限</strong></td><td>限制工具调用次数与重试次数</td><td>控制 Agent 成本尾部风险</td></tr></tbody></table><h3 id="_4-3-从免费到付费的转换设计" tabindex="-1">4.3 从免费到付费的转换设计 <a class="header-anchor" href="#_4-3-从免费到付费的转换设计" aria-label="Permalink to &quot;4.3 从免费到付费的转换设计&quot;">​</a></h3><p><strong>转换触发点</strong>：</p><ol><li><strong>额度触达</strong>：你今天的高级模型 / Agent / 图片额度已用完。</li><li><strong>质量对比</strong>：付费层提供更强模型、更长上下文、更稳定响应。</li><li><strong>时间对比</strong>：付费用户高峰期优先队列。</li><li><strong>工作流锁定</strong>：用户把项目、文档、团队知识库、自动化流程放进产品后，迁移成本上升。</li><li><strong>团队扩展</strong>：个人试用后，需要多人协作、权限、审计、共享上下文。</li></ol><p><strong>典型转化漏斗</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>注册用户: 100%</span></span>
<span class="line"><span>  ├─ 首次价值体验: 40-60%</span></span>
<span class="line"><span>  │    ├─ 7 日留存: 20-30%</span></span>
<span class="line"><span>  │    │    ├─ 触达限制 / 高级需求: 10-15%</span></span>
<span class="line"><span>  │    │    │    ├─ 付费转化: 2-5%</span></span>
<span class="line"><span>  │    │    │    └─ 暂停 / 流失: 8-12%</span></span>
<span class="line"><span>  │    │    └─ 低频继续免费: 10-15%</span></span>
<span class="line"><span>  │    └─ 未留存: 20-30%</span></span>
<span class="line"><span>  └─ 未激活: 40-60%</span></span></code></pre></div><p><strong>A/B 测试重点</strong>：</p><ul><li>免费额度：低额度高转化 vs 高额度高留存；</li><li>限制策略：锁死、慢速、降模型、看广告、购买 credit；</li><li>付费墙文案：强调“更强模型”还是“完成任务”；</li><li>套餐结构：Plus / Pro / Team 是否形成清晰升级路径。</li></ul><hr><h2 id="_5-企业定价策略" tabindex="-1">5. 企业定价策略 <a class="header-anchor" href="#_5-企业定价策略" aria-label="Permalink to &quot;5. 企业定价策略&quot;">​</a></h2><h3 id="_5-1-企业定价维度" tabindex="-1">5.1 企业定价维度 <a class="header-anchor" href="#_5-1-企业定价维度" aria-label="Permalink to &quot;5.1 企业定价维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>C 端</th><th>B 端 / 企业</th></tr></thead><tbody><tr><td>定价模式</td><td>月付订阅 / credits</td><td>席位 + 用量 + 合同承诺</td></tr><tr><td>合同周期</td><td>月付为主</td><td>年付，常见 1-3 年</td></tr><tr><td>价格锚点</td><td>$20-$200/月</td><td>$10K-$500K+/年</td></tr><tr><td>采购决策者</td><td>个人</td><td>IT、财务、法务、业务负责人</td></tr><tr><td>关注点</td><td>体验、功能、价格</td><td>ROI、安全、合规、SLA、数据控制</td></tr><tr><td>谈判空间</td><td>小</td><td>大，尤其是多席位与承诺消费</td></tr></tbody></table><h3 id="_5-2-企业版常见收费项" tabindex="-1">5.2 企业版常见收费项 <a class="header-anchor" href="#_5-2-企业版常见收费项" aria-label="Permalink to &quot;5.2 企业版常见收费项&quot;">​</a></h3><p>企业客户购买的不只是“更高额度”，还包括治理与风险降低能力：</p><table tabindex="0"><thead><tr><th>收费项</th><th>价值</th></tr></thead><tbody><tr><td>SSO / SCIM</td><td>身份统一、入离职管理</td></tr><tr><td>审计日志</td><td>安全追踪、合规检查</td></tr><tr><td>数据保留策略</td><td>满足内部合规与监管要求</td></tr><tr><td>零训练承诺 / 数据隔离</td><td>降低数据泄露和模型训练风险</td></tr><tr><td>管理后台</td><td>控制模型、插件、连接器、使用权限</td></tr><tr><td>用量分析</td><td>控制成本，衡量 ROI</td></tr><tr><td>SLA / 专属支持</td><td>提高业务连续性</td></tr><tr><td>私有部署 / 专属容量</td><td>高敏数据、本地化、低延迟、稳定容量</td></tr></tbody></table><h3 id="_5-3-私有部署与专属容量溢价" tabindex="-1">5.3 私有部署与专属容量溢价 <a class="header-anchor" href="#_5-3-私有部署与专属容量溢价" aria-label="Permalink to &quot;5.3 私有部署与专属容量溢价&quot;">​</a></h3><p>企业客户可能要求私有云、本地部署、专属 GPU、数据驻留或区域处理。这类需求会显著提高交付成本。</p><p><strong>定价策略参考</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>私有部署 / 专属容量价格 = SaaS 等价价格 × 1.5 - 3.0</span></span>
<span class="line"><span>                         + 一次性实施费</span></span>
<span class="line"><span>                         + 年度运维 / 支持费</span></span></code></pre></div><p>加价理由：</p><ul><li>专属算力占用；</li><li>部署、监控、升级、故障响应；</li><li>安全与合规评估；</li><li>定制连接器与内部系统集成；</li><li>SLA 与客户成功成本。</li></ul><h3 id="_5-4-企业用量折扣" tabindex="-1">5.4 企业用量折扣 <a class="header-anchor" href="#_5-4-企业用量折扣" aria-label="Permalink to &quot;5.4 企业用量折扣&quot;">​</a></h3><table tabindex="0"><thead><tr><th>月消费 / 承诺用量</th><th>常见策略</th><th>适用对象</th></tr></thead><tbody><tr><td>&lt; $1K</td><td>标准价</td><td>小团队、实验项目</td></tr><tr><td>$1K-$10K</td><td>小幅折扣 / 技术支持</td><td>中型团队</td></tr><tr><td>$10K-$100K</td><td>阶梯折扣 + 客户成功</td><td>大型企业部门</td></tr><tr><td>$100K+</td><td>协商价 + 专属容量 / 私有部署</td><td>集团级客户</td></tr></tbody></table><h3 id="_5-5-长期合同设计" tabindex="-1">5.5 长期合同设计 <a class="header-anchor" href="#_5-5-长期合同设计" aria-label="Permalink to &quot;5.5 长期合同设计&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 年合同：换取 10-20% 折扣</span></span>
<span class="line"><span>2 年合同：换取 20-30% 折扣</span></span>
<span class="line"><span>3 年合同：换取 30%+ 折扣，但建议绑定最低用量承诺与价格重估条款</span></span></code></pre></div><p>AI 模型成本和能力变化很快，长期合同最好加入：</p><ul><li>模型升级条款；</li><li>用量超额计费规则；</li><li>价格重估窗口；</li><li>数据保护与审计责任；</li><li>供应商模型替换机制；</li><li>最低可用 SLA 和故障赔偿。</li></ul><hr><h2 id="_6-真实行业参考-2026-05" tabindex="-1">6. 真实行业参考（2026-05） <a class="header-anchor" href="#_6-真实行业参考-2026-05" aria-label="Permalink to &quot;6. 真实行业参考（2026-05）&quot;">​</a></h2><blockquote><p>注意：本章只作为“定价结构参考”，不要把具体价格写进长期不维护的产品文档中。推荐在正文使用“截至 2026-05”这样的时间标注，并在文末保留官网来源。</p></blockquote><h3 id="_6-1-openai-chatgpt-从固定订阅走向多层额度与-flexible-usage" tabindex="-1">6.1 OpenAI / ChatGPT：从固定订阅走向多层额度与 flexible usage <a class="header-anchor" href="#_6-1-openai-chatgpt-从固定订阅走向多层额度与-flexible-usage" aria-label="Permalink to &quot;6.1 OpenAI / ChatGPT：从固定订阅走向多层额度与 flexible usage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>用户侧订阅</td><td>ChatGPT 仍采用 Free / Go / Plus / Pro / Business / Enterprise 分层。Plus 仍是 $20/月锚点，Pro 分为更高使用量层级。</td></tr><tr><td>模型口径</td><td>不应再写 GPT-4o 或 GPT-4.1 作为 ChatGPT Plus 主能力；截至 2026-05，Plus 的核心卖点已经转向 GPT-5.5 limits、GPT-5.5 Thinking、Deep Research、Codex 等。</td></tr><tr><td>API 计费</td><td>API 仍按 token 计费，并区分输入、缓存输入、输出、批处理、优先处理等。</td></tr><tr><td>定价逻辑</td><td>C 端用订阅做心理锚点，B 端和 API 用 flexible pricing / usage-based pricing 控制成本。</td></tr><tr><td>PM 洞察</td><td>不要把“具体模型名 + 无限使用”写死，应该写“高级模型额度、推理模式、工具额度随套餐提升”。</td></tr></tbody></table><p><strong>关键洞察</strong>：ChatGPT 的定价已经不是简单的“$20 无限聊天”，而是 <strong>订阅层级 + 高级模型额度 + 工具额度 + flexible usage</strong> 的组合。</p><h3 id="_6-2-anthropic-claude-pro、max、team、enterprise-与-api-并存" tabindex="-1">6.2 Anthropic / Claude：Pro、Max、Team、Enterprise 与 API 并存 <a class="header-anchor" href="#_6-2-anthropic-claude-pro、max、team、enterprise-与-api-并存" aria-label="Permalink to &quot;6.2 Anthropic / Claude：Pro、Max、Team、Enterprise 与 API 并存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>个人版</td><td>Claude Pro 为日常生产力；Max 面向重度用户，提供 5x / 20x 使用量层级。</td></tr><tr><td>团队版</td><td>Team 面向 5-150 人团队，分标准席位和高级席位。</td></tr><tr><td>企业版</td><td>Enterprise 采用席位价 + usage at API rates，更明确地把“使用量成本”暴露给企业客户。</td></tr><tr><td>API 计费</td><td>Opus、Sonnet、Haiku 按 MTok 计费，且有 prompt caching write/read 价格。</td></tr><tr><td>PM 洞察</td><td>“无限使用”是危险表述，应改成“更高用量、限额适用、重度用户可升级”。</td></tr></tbody></table><p><strong>关键洞察</strong>：Claude 的定价越来越清晰地把“人均订阅”和“真实模型消耗”拆开，适合企业采购时做成本归因。</p><h3 id="_6-3-microsoft-365-copilot-办公套件加购-chat-免费入口-agent-计量" tabindex="-1">6.3 Microsoft 365 Copilot：办公套件加购 + Chat 免费入口 + Agent 计量 <a class="header-anchor" href="#_6-3-microsoft-365-copilot-办公套件加购-chat-免费入口-agent-计量" aria-label="Permalink to &quot;6.3 Microsoft 365 Copilot：办公套件加购 + Chat 免费入口 + Agent 计量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>免费入口</td><td>Microsoft 365 Copilot Chat 对符合条件的 Microsoft 365 商业 / 企业客户提供，无额外费用。</td></tr><tr><td>付费层</td><td>Microsoft 365 Copilot Business 作为 Business 订阅的 add-on，需要符合条件的 Microsoft 365 许可证。</td></tr><tr><td>Agent 计费</td><td>自定义 Agent 可按 metered basis 使用，Azure / Copilot Studio 容量可能参与计费。</td></tr><tr><td>模型口径</td><td>页面已强调使用最新 OpenAI models，而不是旧的 GPT-4o 口径。</td></tr><tr><td>PM 洞察</td><td>大型办公软件的 AI 定价不是单独卖“聊天”，而是卖“嵌入工作流 + 组织数据 + 企业治理”。</td></tr></tbody></table><p><strong>关键洞察</strong>：Microsoft 的策略是用 Copilot Chat 做入口，用 Office 工作流和企业数据上下文做付费转化，用 Agent metering 控制自动化成本。</p><h3 id="_6-4-cursor-从-高级调用次数-转向-订阅-included-model-usage-on-demand" tabindex="-1">6.4 Cursor：从“高级调用次数”转向“订阅 + included model usage + on-demand” <a class="header-anchor" href="#_6-4-cursor-从-高级调用次数-转向-订阅-included-model-usage-on-demand" aria-label="Permalink to &quot;6.4 Cursor：从“高级调用次数”转向“订阅 + included model usage + on-demand”&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>个人版</td><td>Hobby 免费，Pro 起步，另有 Pro+ / Ultra 面向更高频 Agent 用户。</td></tr><tr><td>团队版</td><td>Teams 按用户收费，增加团队上下文、规则、自动化、安全审查、SSO、用量分析等。</td></tr><tr><td>超额使用</td><td>每个计划包含一定 model usage，超过后可用 on-demand usage，按欠费后结算。</td></tr><tr><td>PM 洞察</td><td>编程助手已经从“补全工具”变成“Agent 工作台”，定价必须覆盖长期运行的 Agent 成本。</td></tr></tbody></table><p><strong>关键洞察</strong>：不要再写“500 次高级调用 + 小模型无限”这类旧口径，应该写“包含模型用量 + 超额按量 + Agent 用户分层”。</p><h3 id="_6-5-github-copilot-个人、团队、企业与-premium-requests" tabindex="-1">6.5 GitHub Copilot：个人、团队、企业与 premium requests <a class="header-anchor" href="#_6-5-github-copilot-个人、团队、企业与-premium-requests" aria-label="Permalink to &quot;6.5 GitHub Copilot：个人、团队、企业与 premium requests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>价格 / 结构</th><th>核心差异</th></tr></thead><tbody><tr><td>Copilot Free</td><td>免费</td><td>有限补全、聊天和 premium requests</td></tr><tr><td>Copilot Pro</td><td>$10/月</td><td>更高 premium requests，个人开发者主力层</td></tr><tr><td>Copilot Pro+</td><td>$39/月</td><td>更高 premium requests，适合高级模型和重度使用</td></tr><tr><td>Copilot Business</td><td>$19/席位/月</td><td>组织管理、策略控制、企业数据保护</td></tr><tr><td>Copilot Enterprise</td><td>$39/席位/月</td><td>更高 premium requests、企业级集成与治理</td></tr></tbody></table><p><strong>关键洞察</strong>：编程类 AI 产品越来越采用 <strong>基础订阅 + premium requests + 高级模型 / Agent 额度</strong>，而不是简单“无限补全”。</p><h3 id="_6-6-notion-ai-从独立-ai-加购转向-business-enterprise-内置-custom-agent-credits" tabindex="-1">6.6 Notion AI：从独立 AI 加购转向 Business / Enterprise 内置 + Custom Agent credits <a class="header-anchor" href="#_6-6-notion-ai-从独立-ai-加购转向-business-enterprise-内置-custom-agent-credits" aria-label="Permalink to &quot;6.6 Notion AI：从独立 AI 加购转向 Business / Enterprise 内置 + Custom Agent credits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>Notion AI</td><td>Notion AI 已更多地与 Business / Enterprise 计划绑定，核心 AI 功能如 Notion Agent、AI Meeting Notes、Enterprise Search 被打包进高阶计划。</td></tr><tr><td>Custom Agents</td><td>从 2026-05-04 起，Custom Agents 使用 Notion credits，$10 / 1,000 credits，按任务复杂度消耗。</td></tr><tr><td>成本控制</td><td>Credits 共享在 workspace 层级，月度重置，不结转；可设置 agent credit limits。</td></tr><tr><td>PM 洞察</td><td>对知识库 SaaS 来说，普通 AI 助手适合打包进高阶套餐，自动化 Agent 更适合单独 credit 化。</td></tr></tbody></table><p><strong>关键洞察</strong>：Notion 的变化说明，AI 功能会从“单独加购”逐渐变成“套餐内置”，但高成本、后台自动运行的 Agent 会被 credit 化。</p><h3 id="_6-7-midjourney-不是简单按张数-而是订阅-gpu-时间-队列优先级" tabindex="-1">6.7 Midjourney：不是简单按张数，而是订阅 + GPU 时间 + 队列优先级 <a class="header-anchor" href="#_6-7-midjourney-不是简单按张数-而是订阅-gpu-时间-队列优先级" aria-label="Permalink to &quot;6.7 Midjourney：不是简单按张数，而是订阅 + GPU 时间 + 队列优先级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>分析</th></tr></thead><tbody><tr><td>套餐</td><td>Basic、Standard、Pro、Mega 四档订阅。</td></tr><tr><td>计费核心</td><td>Fast GPU time、Relax Mode、并发任务、Stealth Mode 等，而不是单纯“多少张图”。</td></tr><tr><td>PM 洞察</td><td>图像生成产品可以把成本抽象为 GPU 时间，让用户更容易理解“速度、优先级、并发”的价值。</td></tr></tbody></table><p><strong>关键洞察</strong>：创作类 AI 的核心不是“每张图多少钱”，而是“创作吞吐量 + 等待时间 + 商业使用控制”。</p><h3 id="_6-8-行业价格汇总表-建议每季度复核" tabindex="-1">6.8 行业价格汇总表（建议每季度复核） <a class="header-anchor" href="#_6-8-行业价格汇总表-建议每季度复核" aria-label="Permalink to &quot;6.8 行业价格汇总表（建议每季度复核）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产品</th><th>免费层</th><th>入门 / Pro</th><th>团队 / 企业</th><th>核心定价模式</th></tr></thead><tbody><tr><td>ChatGPT</td><td>有</td><td>Plus $20，Pro 更高用量</td><td>Business / Enterprise</td><td>Freemium + 订阅 + flexible usage</td></tr><tr><td>Claude</td><td>有</td><td>Pro / Max</td><td>Team / Enterprise</td><td>订阅 + 更高用量 + API 用量</td></tr><tr><td>Gemini</td><td>有</td><td>Google AI Pro / Ultra</td><td>Workspace / Enterprise</td><td>订阅 + Google 生态打包</td></tr><tr><td>Microsoft 365 Copilot</td><td>Copilot Chat</td><td>Copilot Business add-on</td><td>企业合约</td><td>办公套件加购 + Agent metering</td></tr><tr><td>Cursor</td><td>Hobby</td><td>Pro / Pro+ / Ultra</td><td>Teams / Enterprise</td><td>订阅 + included usage + on-demand</td></tr><tr><td>GitHub Copilot</td><td>Free</td><td>Pro / Pro+</td><td>Business / Enterprise</td><td>订阅 + premium requests</td></tr><tr><td>Notion AI</td><td>试用 / 限量</td><td>Business 内置</td><td>Enterprise + credits</td><td>高阶套餐内置 + Custom Agent credits</td></tr><tr><td>Midjourney</td><td>通常无长期免费层</td><td>Basic / Standard / Pro / Mega</td><td>—</td><td>订阅 + GPU 时间</td></tr><tr><td>Perplexity</td><td>有</td><td>Pro</td><td>Enterprise</td><td>搜索 / 研究订阅</td></tr><tr><td>Grammarly / Superhuman</td><td>有</td><td>Pro</td><td>Enterprise</td><td>写作 AI + 团队协作 + 企业治理</td></tr></tbody></table><hr><h2 id="_7-附录-定价工具箱" tabindex="-1">7. 附录：定价工具箱 <a class="header-anchor" href="#_7-附录-定价工具箱" aria-label="Permalink to &quot;7. 附录：定价工具箱&quot;">​</a></h2><h3 id="_7-1-定价检查清单" tabindex="-1">7.1 定价检查清单 <a class="header-anchor" href="#_7-1-定价检查清单" aria-label="Permalink to &quot;7.1 定价检查清单&quot;">​</a></h3><p>发布 AI 产品定价前，请逐项检查：</p><ul><li>[ ] <strong>单位经济学</strong>：单次请求、单次任务、单次 Agent run 的真实成本是多少？</li><li>[ ] <strong>模型路由策略</strong>：不同用户、任务、套餐分别走什么模型？</li><li>[ ] <strong>毛利率验证</strong>：扣除推理、检索、工具、存储、支持后的毛利是否达标？</li><li>[ ] <strong>免费层成本上限</strong>：最坏情况下免费用户会烧多少钱？</li><li>[ ] <strong>滥用防护</strong>：批量注册、脚本调用、自动化刷量是否可控？</li><li>[ ] <strong>转化路径</strong>：用户什么时候遇到限制？限制是否自然触发付费？</li><li>[ ] <strong>企业能力</strong>：是否有 SSO、SCIM、审计、数据保留、用量分析？</li><li>[ ] <strong>账单保护</strong>：是否有预算上限、告警、暂停机制？</li><li>[ ] <strong>降本预案</strong>：模型成本下降 50% 时，是否调整价格、额度或毛利？</li><li>[ ] <strong>季度复核</strong>：竞品价格、模型成本、用户用量结构是否已更新？</li></ul><h3 id="_7-2-常见定价错误" tabindex="-1">7.2 常见定价错误 <a class="header-anchor" href="#_7-2-常见定价错误" aria-label="Permalink to &quot;7.2 常见定价错误&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误</th><th>后果</th><th>如何避免</th></tr></thead><tbody><tr><td>免费层太慷慨</td><td>成本失控，免费用户不转化</td><td>按“完成 1-3 个工作流”设计免费额度</td></tr><tr><td>承诺无限高级模型</td><td>重度用户造成亏损</td><td>使用 fair use、credits、优先级和动态限额</td></tr><tr><td>只按席位不看用量</td><td>高使用组织亏损</td><td>席位 + included usage + 超额计费</td></tr><tr><td>只按用量计费</td><td>用户焦虑，使用被抑制</td><td>把 token 抽象成 messages / credits / runs</td></tr><tr><td>套餐差异不清晰</td><td>用户不知道为什么升级</td><td>差异化模型、上下文、速度、工具、治理能力</td></tr><tr><td>不做账单保护</td><td>客户因意外账单流失</td><td>预算上限、提醒、自动暂停</td></tr><tr><td>文档写死模型名</td><td>文章很快过时</td><td>写模型等级与能力，不写长期会变的具体限额</td></tr></tbody></table><h3 id="_7-3-定价变更策略" tabindex="-1">7.3 定价变更策略 <a class="header-anchor" href="#_7-3-定价变更策略" aria-label="Permalink to &quot;7.3 定价变更策略&quot;">​</a></h3><p>AI 行业变化快，定价需要持续优化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 涨价策略</span></span>
<span class="line"><span>   前提：模型升级、功能增加、成本上涨、使用量超预期</span></span>
<span class="line"><span>   方法：新用户新价，老用户锁价 3-12 个月</span></span>
<span class="line"><span>   风险：用户流失和舆论反弹</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 降价策略</span></span>
<span class="line"><span>   前提：推理成本下降、竞争加剧、获客需要</span></span>
<span class="line"><span>   方法：直接降价、增加额度、推出低价层</span></span>
<span class="line"><span>   风险：老用户要求补偿，价格锚点降低</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 重构策略</span></span>
<span class="line"><span>   前提：从聊天变 Agent，从单模型变多模型，从个人产品变团队产品</span></span>
<span class="line"><span>   方法：订阅 + credits / usage 的混合迁移</span></span>
<span class="line"><span>   风险：用户理解成本高，需要清晰迁移说明</span></span></code></pre></div><h3 id="_7-4-推荐监控指标" tabindex="-1">7.4 推荐监控指标 <a class="header-anchor" href="#_7-4-推荐监控指标" aria-label="Permalink to &quot;7.4 推荐监控指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>健康值</th><th>预警值</th></tr></thead><tbody><tr><td>月毛利率</td><td>&gt; 65%</td><td>&lt; 50%</td></tr><tr><td>免费 → 付费转化率</td><td>&gt; 3%</td><td>&lt; 1%</td></tr><tr><td>付费用户月留存</td><td>&gt; 90%</td><td>&lt; 80%</td></tr><tr><td>平均每付费用户推理成本</td><td>&lt; 订阅价 30%</td><td>&gt; 订阅价 50%</td></tr><tr><td>免费用户月成本</td><td>&lt; $0.50</td><td>&gt; $2.00</td></tr><tr><td>高级模型请求占比</td><td>可控且下降</td><td>持续上升</td></tr><tr><td>Agent run 成功率</td><td>&gt; 90%</td><td>&lt; 75%</td></tr><tr><td>Agent 平均步骤数</td><td>稳定</td><td>快速上升</td></tr><tr><td>企业客户 LTV/CAC</td><td>&gt; 5x</td><td>&lt; 3x</td></tr><tr><td>账单超额投诉率</td><td>&lt; 1%</td><td>&gt; 3%</td></tr></tbody></table><h3 id="_7-5-文档维护建议" tabindex="-1">7.5 文档维护建议 <a class="header-anchor" href="#_7-5-文档维护建议" aria-label="Permalink to &quot;7.5 文档维护建议&quot;">​</a></h3><p>AI 定价文章非常容易过时，建议采用以下维护规则：</p><ol><li><strong>具体价格集中放在第 6 章和参考来源</strong>，不要散落在全文；</li><li><strong>每季度复核一次行业价格表</strong>；</li><li><strong>正文尽量描述定价结构，而不是写死具体额度</strong>；</li><li><strong>所有案例标注日期</strong>，例如“截至 2026-05”；</li><li><strong>当模型名变化时，优先改成能力层级</strong>，例如“旗舰模型 / mini 模型 / reasoning 模型 / agent 模型”。</li></ol><hr><h2 id="_8-参考来源" tabindex="-1">8. 参考来源 <a class="header-anchor" href="#_8-参考来源" aria-label="Permalink to &quot;8. 参考来源&quot;">​</a></h2><blockquote><p>以下来源用于更新第 2、4、6 章的价格与套餐口径。价格、额度、模型可用性可能随地区、时间、账户类型变化，落地前请以官网为准。</p></blockquote><ul><li>OpenAI API Pricing: <a href="https://openai.com/api/pricing/" target="_blank" rel="noreferrer">https://openai.com/api/pricing/</a></li><li>ChatGPT Pricing: <a href="https://openai.com/chatgpt/pricing/" target="_blank" rel="noreferrer">https://openai.com/chatgpt/pricing/</a></li><li>OpenAI Help Center — What is ChatGPT Plus: <a href="https://help.openai.com/en/articles/6950777-what-is-chatgpt-plus" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/6950777-what-is-chatgpt-plus</a></li><li>Claude Pricing: <a href="https://claude.com/pricing" target="_blank" rel="noreferrer">https://claude.com/pricing</a></li><li>Microsoft 365 Copilot Pricing: <a href="https://www.microsoft.com/en-sg/microsoft-365-copilot/pricing" target="_blank" rel="noreferrer">https://www.microsoft.com/en-sg/microsoft-365-copilot/pricing</a></li><li>Cursor Pricing: <a href="https://cursor.com/pricing" target="_blank" rel="noreferrer">https://cursor.com/pricing</a></li><li>GitHub Docs — Plans for GitHub Copilot: <a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/get-started/plans</a></li><li>Notion Help Center — Custom Agent pricing: <a href="https://www.notion.com/help/custom-agent-pricing" target="_blank" rel="noreferrer">https://www.notion.com/help/custom-agent-pricing</a></li><li>Midjourney Docs — Comparing Midjourney Plans: <a href="https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans" target="_blank" rel="noreferrer">https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans</a></li><li>Google AI Pro &amp; Ultra: <a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">https://gemini.google/subscriptions/</a></li></ul><hr><blockquote><p><strong>结语</strong>：AI 产品定价不是一次性决策，而是持续优化过程。最成功的 AI 产品经理，既要理解成本结构，也要理解用户心理；既要会算 token 成本，也要会把成本包装成用户能感知的价值。真正好的定价，不是“便宜”或“贵”，而是在成本、价值、体验、竞争和增长之间找到可持续的平衡。</p></blockquote>`,171)])])}const u=a(d,[["render",r]]);export{g as __pageData,u as default};
